-- Transactional authorization/state checks; storage rows here have NO blob bytes.
begin;
do $$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();pet uuid:=gen_random_uuid();photo uuid:=gen_random_uuid();
 job uuid;late_job uuid;media uuid;path text;key uuid:=gen_random_uuid();record jsonb;denied boolean;checks integer:=0;
begin
 insert into auth.users(id,instance_id,aud,role,email,created_at,updated_at) values
 (a,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',a::text||'@example.invalid',now(),now()),
 (b,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',b::text||'@example.invalid',now(),now());
 insert into mefrion_private.pets(id,owner_id,name,species) values(pet,a,'合成公開試験','dog');
 insert into mefrion_private.members(pet_id,user_id) values(pet,b);
 insert into mefrion_private.photos(id,pet_id,provider_id,object_path,request_key,state) values(photo,pet,b,pet::text||'/'||photo::text||'.jpg',gen_random_uuid(),'ready');
 if has_function_privilege('authenticated','public.mefrion_publication_batch()','execute') or has_function_privilege('anon','public.mefrion_public_image_path(uuid,uuid)','execute') then raise exception 'worker privileges leaked';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.mefrion_set_public_profile(pet,true,false);exception when others then if sqlerrm='explicit_publication_required' then denied:=true;else raise;end if;end;
 if not denied then raise exception 'profile explicit consent bypass';end if;checks:=checks+1;
 perform public.mefrion_set_public_profile(pet,true,true);
 denied:=false;begin perform public.mefrion_request_publication(pet,array[photo],'','post',key,true);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'provider consent bypass';end if;checks:=checks+1;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.mefrion_consent(photo,'sns',true);
 denied:=false;begin perform public.mefrion_request_publication(pet,array[photo],'','post',key,true);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'family published without owner';end if;checks:=checks+1;
 execute 'reset role';perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.mefrion_request_publication(pet,array[photo],'','post',key,false);exception when others then if sqlerrm='explicit_publication_required' then denied:=true;else raise;end if;end;
 if not denied then raise exception 'post explicit consent bypass';end if;checks:=checks+1;
 record:=public.mefrion_request_publication(pet,array[photo],'synthetic post','post',key,true);job:=(record->>'id')::uuid;
 if public.mefrion_request_publication(pet,array[photo],'synthetic post','post',key,true)<>record then raise exception 'retry changed post';end if;checks:=checks+1;
 denied:=false;begin perform public.mefrion_request_publication(pet,array[photo],'different body','post',key,true);exception when others then if sqlerrm='idempotency_conflict' then denied:=true;else raise;end if;end;
 if not denied then raise exception 'conflicting retry accepted';end if;checks:=checks+1;
 if exists(select 1 from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text) then raise exception 'pending post exposed';end if;checks:=checks+1;
 execute 'reset role';
 select id,object_path into media,path from mefrion_private.public_media where post_id=job;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 perform public.mefrion_publication_batch();
 if public.mefrion_publication_finish(job) then raise exception 'missing derivative accepted';end if;checks:=checks+1;
 execute 'reset role';
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 record:=public.mefrion_request_publication(pet,array[photo],'synthetic derivative','post',gen_random_uuid(),true);job:=(record->>'id')::uuid;
 execute 'reset role';select id,object_path into media,path from mefrion_private.public_media where post_id=job;
 insert into storage.objects(bucket_id,name) values('public-derived',path);
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 perform public.mefrion_publication_batch();
 if not public.mefrion_publication_finish(job) then raise exception 'valid derivative denied';end if;checks:=checks+1;
 if public.mefrion_public_image_path(media)<>path then raise exception 'public derivative gateway denied';end if;checks:=checks+1;
 execute 'reset role';perform set_config('request.jwt.claims','{"role":"anon"}',true);execute 'set local role anon';
 select item into record from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text;
 if record is null or record ? 'actor_id' or record ? 'source_id' or record ? 'object_path' or record ? 'provider_id' or (record->'media'->>0)<>media::text then raise exception 'public projection leaked private metadata';end if;checks:=checks+1;
 execute 'reset role';insert into mefrion_private.social_blocks values(b,a);
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);execute 'set local role authenticated';
 if exists(select 1 from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text) then raise exception 'block bypass';end if;checks:=checks+1;
 execute 'reset role';delete from mefrion_private.social_blocks where actor_id=b and target_id=a;
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.mefrion_consent(photo,'twins',true);
 if not exists(select 1 from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text) then raise exception 'independent purpose changed SNS';end if;checks:=checks+1;
 perform public.mefrion_consent(photo,'sns',false);
 if exists(select 1 from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text) then raise exception 'withdrawn consent exposed';end if;checks:=checks+1;
 execute 'reset role';
 if not exists(select 1 from mefrion_private.deletion_outbox where object_path=path and bucket='public-derived') then raise exception 'derived purge not queued';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 if public.mefrion_public_image_path(media) is not null then raise exception 'withdrawn derivative access';end if;checks:=checks+1;
 execute 'reset role';perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.mefrion_consent(photo,'sns',true);
 if exists(select 1 from jsonb_array_elements(public.mefrion_public_feed()) item where item->>'id'=job::text) then raise exception 'regrant revived post';end if;checks:=checks+1;
 execute 'reset role';perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 record:=public.mefrion_request_publication(pet,array[photo],'late worker','post',gen_random_uuid(),true);late_job:=(record->>'id')::uuid;
 execute 'reset role';select object_path into path from mefrion_private.public_media where post_id=late_job;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';perform public.mefrion_publication_batch();execute 'reset role';
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',json_build_object('sub',b,'role','authenticated')::text,true);execute 'set local role authenticated';perform public.mefrion_consent(photo,'sns',false);execute 'reset role';
 update mefrion_private.deletion_outbox set state='done' where object_path=path;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);execute 'set local role service_role';
 if public.mefrion_publication_finish(late_job) then raise exception 'late revoked worker published';end if;execute 'reset role';
 if not exists(select 1 from mefrion_private.deletion_outbox where object_path=path and state='pending') then raise exception 'late upload purge not requeued';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',json_build_object('sub',a,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.mefrion_delete_photo(photo);execute 'reset role';checks:=checks+1;
 perform set_config('mefrion.publication_checks',checks::text,true);
end $$;
select current_setting('mefrion.publication_checks') as passed_publication_checks,'simulated Auth/storage metadata only; no blob bytes' as scope;
rollback;
